const UNITS = { d: 86400000, h: 3600000, m: 60000, s: 1000 };

// A canonical duration: each unit optional, at most once, largest first.
const CANONICAL = /^(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/;

function parseDuration(input) {
  const groups = typeof input === 'string' ? input.match(CANONICAL) : null;
  if (!groups || input === '') {
    throw new RangeError(`invalid duration: ${JSON.stringify(input)}`);
  }
  let total = 0;
  for (let i = 1; i < groups.length; i++) {
    if (groups[i] === undefined) continue;
    total += Number(groups[i]) * Object.values(UNITS)[i - 1];
  }
  return total;
}

function formatDuration(ms) {
  const parts = [];
  for (const [unit, size] of Object.entries(UNITS)) {
    const n = Math.floor(ms / size);
    if (n > 0) parts.push(`${n}${unit}`);
    ms -= n * size;
  }
  return parts.join('') || '0s';
}

